<?php
require __DIR__.'/includes/bootstrap.php';require_login();$memberId=current_member_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$name=trim($_POST['name']??'');$amount=parse_amount_ro($_POST['amount']??'');if($name&&$amount>0){$cycle=$_POST['billing_cycle']==='yearly'?'yearly':'monthly';$s=$pdo->prepare('INSERT INTO subscriptions(name,amount,billing_cycle,renewal_day,renewal_month,category,created_by_member_id) VALUES(?,?,?,?,?,?,?)');$s->execute([$name,$amount,$cycle,max(1,min(31,(int)($_POST['renewal_day']??1))),$cycle==='yearly'?max(1,min(12,(int)($_POST['renewal_month']??1))):null,trim($_POST['category']??'Abonamente')?:'Abonamente',$memberId]);log_activity($pdo,'subscription_added','subscription',(int)$pdo->lastInsertId(),$name);}}
 if($action==='toggle'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE subscriptions SET active=1-active WHERE id=?')->execute([$id]);}
 if($action==='delete'){$id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM subscriptions WHERE id=?')->execute([$id]);}
 header('Location:/subscriptions.php');exit;
}
$rows=$pdo->query('SELECT s.*,m.name creator FROM subscriptions s LEFT JOIN family_members m ON m.id=s.created_by_member_id ORDER BY s.active DESC,s.name')->fetchAll();$monthly=0;$yearly=0;foreach($rows as $r){if(!$r['active'])continue;$yearly+=(float)$r['amount']*($r['billing_cycle']==='monthly'?12:1);$monthly+=(float)$r['amount']/($r['billing_cycle']==='yearly'?12:1);}
$pageTitle='Abonamente';$active='money';require __DIR__.'/includes/layout_top.php';
?>
<section class="hero-card subtle"><div><span class="eyebrow">Costuri recurente</span><h2><?=money_ro($monthly)?> / lună</h2><p><?=money_ro($yearly)?> pe an dacă păstrezi toate abonamentele active.</p></div><button class="btn primary small" data-open-sheet="subSheet"><?=icon('plus')?> Adaugă</button></section>
<div class="card-list"><?php if(!$rows):?><div class="empty">Nu ai abonamente adăugate.</div><?php endif;?><?php foreach($rows as $r):?><article class="info-card <?=$r['active']?'':'muted-card'?>"><span class="mini-icon purple"><?=icon('repeat')?></span><div><strong><?=e($r['name'])?></strong><span><?=e($r['billing_cycle']==='monthly'?'Lunar':'Anual')?> · ziua <?=$r['renewal_day']?><?=$r['creator']?' · '.e($r['creator']):''?></span></div><div class="right"><b><?=money_ro($r['amount'])?></b><div class="inline-actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button"><?=$r['active']?'Pauză':'Activează'?></button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button danger">Șterge</button></form></div></div></article><?php endforeach;?></div>
<div class="modal" id="subSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><span class="eyebrow">Buget</span><h2>Abonament nou</h2></div><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Denumire<input name="name" required placeholder="Ex: Netflix"></label><label>Sumă<input name="amount" inputmode="decimal" required placeholder="59,00"></label><label>Frecvență<select name="billing_cycle"><option value="monthly">Lunar</option><option value="yearly">Anual</option></select></label><div class="form-grid"><label>Ziua reînnoirii<input name="renewal_day" inputmode="numeric" value="1"></label><label>Luna (doar anual)<input name="renewal_month" inputmode="numeric" placeholder="1-12"></label></div><button class="btn primary wide">Salvează</button></form></section></div>
